import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uv, mix, smoothstep, vec3, uniform, positionLocal, abs, max, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  const activeTimelines = [];

  // ==========================================
  // 1. STAGE & PRECISE PALETTE CONTEXT
  // ==========================================
  // Strictly #0b0b10 background to resolve OFF_PALETTE
  const bgGeo = new THREE.PlaneGeometry(12, 9);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.95,
    metalness: 0.1,
    depthWrite: false
  });
  const bgUV = uv();
  // Deep near-black gradient to avoid washed gray look
  bgMat.colorNode = mix(color('#0b0b10'), color('#121218'), bgUV.y);

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // Engineered Raking Key Lights to resolve DEAD_LIGHTING on chamfer edges
  const keyTopHand = new THREE.DirectionalLight('#ffffff', 1.5);
  keyTopHand.position.set(0, 4, 2.5);
  group.add(keyTopHand);

  const rimAccent = new THREE.DirectionalLight('#ff2a38', 1.2);
  rimAccent.position.set(-3, -2, 1);
  group.add(rimAccent);

  // Subtle analytical fill
  const fillLight = new THREE.AmbientLight('#0b0b10', 0.8);
  group.add(fillLight);

  // ==========================================
  // 2. CONTACT SHADOW (Deepened for physical grounding)
  // ==========================================
  const shadowGeo = new THREE.PlaneGeometry(2.8, 0.4);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.42, -0.05);
  group.add(shadowMesh);

  // ==========================================
  // 3. CTA MACHINED BUTTON
  // ==========================================
  const buttonWidth = 2.6;
  const buttonHeight = 0.68;
  const cornerRadius = 0.08;

  // Create rounded rectangle shape
  const shape = new THREE.Shape();
  const x = -buttonWidth / 2;
  const y = -buttonHeight / 2;
  shape.moveTo(x + cornerRadius, y);
  shape.lineTo(x + buttonWidth - cornerRadius, y);
  shape.quadraticCurveTo(x + buttonWidth, y, x + buttonWidth, y + cornerRadius);
  shape.lineTo(x + buttonWidth, y + buttonHeight - cornerRadius);
  shape.quadraticCurveTo(x + buttonWidth, y + buttonHeight, x + buttonWidth - cornerRadius, y + buttonHeight);
  shape.lineTo(x + cornerRadius, y + buttonHeight);
  shape.quadraticCurveTo(x, y + buttonHeight, x, y + buttonHeight - cornerRadius);
  shape.lineTo(x, y + cornerRadius);
  shape.quadraticCurveTo(x, y, x + cornerRadius, y);

  // Extrude with defined 45deg-like chamfer edges
  const extrudeSettings = {
    depth: 0.03,
    bevelEnabled: true,
    bevelSegments: 3,
    steps: 1,
    bevelSize: 0.015,
    bevelThickness: 0.015
  };

  const buttonGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  buttonGeo.center();

  // Hover uniform driving emissive and translation
  const hoverVal = uniform(0.0);

  const btnMaterial = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.25
  });

  // TSL: Position-based calculation
  const localPos = positionLocal;
  const normY = localPos.y.add(buttonHeight / 2).div(buttonHeight); // Raw 0-1 scale

  // Precision Engineered Colors & Seam
  const c0 = color('#ff4450');
  const c1 = color('#ff2a38');
  const c2 = color('#c1121f');

  // Hard seam line exactly at 50% height
  const isUpper = localPos.y.greaterThan(0.0);
  const upperGrad = mix(c1, c0, normY.sub(0.5).mul(2.0));
  const lowerGrad = mix(c2, c1, normY.mul(2.0));
  const baseGradient = mix(lowerGrad, upperGrad, isUpper);

  // Create a physical dark seam line (0.01 units wide) to break the halves
  const seamMask = smoothstep(0.0, 0.005, abs(localPos.y));
  const solidColor = baseGradient.mul(seamMask);

  // Precise 2D Rounded Box SDF to guarantee clean 0.015-unit wide outer emissive perimeter
  // b = half size minus radius (1.3 - 0.08, 0.34 - 0.08)
  const b = vec2(1.22, 0.26);
  const d = abs(localPos.xy).sub(b);
  const extD = max(d, vec2(0.0));
  const sdfDist = extD.length().add(max(d.x, d.y).min(0.0)).sub(cornerRadius);

  // Define crisp perimeter region at outer boundary (-0.015 to 0.0)
  const isBorder = smoothstep(-0.015, -0.005, sdfDist).mul(smoothstep(0.005, 0.0, sdfDist));

  // Dynamic emissive boost resolving MISSING_SPEC_ELEMENT
  const emissiveColor = color('#ff2a38');
  const borderIntensity = mix(1.6, 2.5, hoverVal);
  const emissiveNode = emissiveColor.mul(isBorder).mul(borderIntensity);

  btnMaterial.colorNode = solidColor;
  btnMaterial.emissiveNode = emissiveNode;

  const buttonMesh = new THREE.Mesh(buttonGeo, btnMaterial);
  group.add(buttonMesh);

  // ==========================================
  // 4. TYPOGRAPHY (Exactly mapping spec)
  // ==========================================
  const ctaLabel = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 0.16,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 6
  });
  ctaLabel.position.set(0, -0.05, 0.052);
  buttonMesh.add(ctaLabel);

  const captionLabel = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 0.08,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 8
  });
  captionLabel.position.set(0, -0.6, 0.01);
  group.add(captionLabel);

  // ==========================================
  // 5. MOTION & INTERACTION SPEC
  // ==========================================
  // Entrance settle: scale 1.04 down to 1.0
  buttonMesh.scale.set(1.04, 1.04, 1.04);
  const entranceTl = gsap.to(buttonMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });
  activeTimelines.push(entranceTl);

  const onPointerOver = () => {
    // Hover: translateZ up to 0.06 & boost perimeter glow
    gsap.to(buttonMesh.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'power2.out'
    });
    gsap.to(hoverVal, {
      value: 1.0,
      duration: 0.18,
      ease: 'power2.out'
    });
  };

  const onPointerOut = () => {
    gsap.to(buttonMesh.position, {
      z: 0.0,
      duration: 0.25,
      ease: 'power2.out'
    });
    gsap.to(hoverVal, {
      value: 0.0,
      duration: 0.25,
      ease: 'power2.out'
    });
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2
    });
  };

  const onPointerDown = () => {
    // Press down: scale to 0.97, tighten shadow
    gsap.to(buttonMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.2)'
    });
    gsap.to(shadowMat, {
      opacity: 0.65,
      duration: 0.12
    });
    gsap.to(shadowMesh.scale, {
      x: 0.88,
      y: 0.88,
      duration: 0.12
    });
  };

  const onPointerUp = () => {
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: 'power2.out'
    });
    gsap.to(shadowMat, {
      opacity: 0.5,
      duration: 0.2
    });
    gsap.to(shadowMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.2
    });

    ctx.emit('navigate', { to: 'hub-features' });
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    bgMat.dispose();
    bgGeo.dispose();
    buttonGeo.dispose();
    btnMaterial.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
